def la_so_nguyen_to(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i = i + 1
    return True

if la_so_nguyen_to(7):
    print("7 là số nguyên tố")
if la_so_nguyen_to(12):
    print("12 là số nguyên tố")
else:
    print("12 không phải số nguyên tố")

# Xem mỗi số chia hết cho những số nào
for n in [12, 7]:
    dem = 0
    for i in range(1, n + 1):
        if n % i == 0:
            print(i, end=" ")
            dem = dem + 1
    print()
    print("Số", n, "chia hết cho", dem, "số")

